// n8n Code node: build one summary email from the RED and AMBER rows
const esc = s => String(s ?? '').replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const fmt = d => d ? new Date(d + 'T00:00:00Z').toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: 'numeric', timeZone: 'UTC' }) : 'unknown';
const items = $input.all().map(i => i.json);
const order = { RED: 0, AMBER: 1 };
const fl = x => (x.float_wd === '' || x.float_wd == null ? -999 : Number(x.float_wd));
items.sort((a, b) => (order[a.rag] - order[b.rag]) || (fl(a) - fl(b)));

const red = items.filter(i => i.rag === 'RED').length;
const amber = items.filter(i => i.rag === 'AMBER').length;
const colour = { RED: '#c83232', AMBER: '#b87800' };
const td = 'padding:7px 10px;border-bottom:1px solid #e3e6eb;vertical-align:top;';
const action = { escalation: 'Escalate', chaser: 'Chase supplier', internal_note: 'Internal check', none: '-' };

const rows = items.map(i => `<tr>
  <td style="${td}white-space:nowrap"><b>${esc(i.item_id)}</b></td>
  <td style="${td}">${esc(i.description)}</td>
  <td style="${td}"><span style="background:${colour[i.rag]};color:#fff;border-radius:10px;padding:2px 8px;font-size:12px;font-weight:bold">${esc(i.rag)}</span></td>
  <td style="${td}white-space:nowrap">${fmt(i.on_site_forecast)}</td>
  <td style="${td}white-space:nowrap">${fmt(i.ros_date)}</td>
  <td style="${td}text-align:right">${(i.float_wd === '' || i.float_wd == null) ? '-' : esc(i.float_wd)}</td>
  <td style="${td}">${esc(i.reasons)}</td>
  <td style="${td}white-space:nowrap">${esc(action[i.action] || i.action)}</td>
</tr>`).join('');

const th = 'text-align:left;padding:7px 10px;background:#f5f7fa;color:#5b6472;font-size:12px;';
const html = `<div style="font-family:Arial,sans-serif;font-size:14px;color:#14181f;max-width:900px">
<p>Good morning,</p>
<p>LeadTime Guard checked all long-lead items. <b>${red} red</b> and <b>${amber} amber</b> items need attention today:</p>
<table style="border-collapse:collapse;width:100%;font-size:13px">
<tr><th style="${th}">Item</th><th style="${th}">Description</th><th style="${th}">Status</th><th style="${th}">On site</th><th style="${th}">Needed</th><th style="${th}">Float (wd)</th><th style="${th}">Why</th><th style="${th}">Next step</th></tr>
${rows}
</table>
<p>Draft emails to suppliers are waiting for approval in the <a href="https://leadtime-guard-site.vercel.app/dashboard.html">dashboard</a>. Nothing is sent to suppliers automatically.</p>
<p style="color:#5b6472;font-size:12px">Sent by the LeadTime Guard n8n workflow. Portfolio demo with synthetic data.</p>
</div>`;

return [{ json: { subject: `LeadTime Guard: ${red} red, ${amber} amber items today`, html, red, amber } }];
